#include <zephyr/ztest.h>
#include <zephyr/storage/stream_flash.h>
#include <zephyr/device.h>
#include <zephyr/drivers/flash.h>
#include <zephyr/logging/log.h>
#include <zephyr/storage/flash_map.h>

LOG_MODULE_REGISTER(STREAM_FLASH_TEST, LOG_LEVEL_DBG);

/* Use the partition configured for stream_flash, typically 'storage_partition' */
#define TEST_FLASH_AREA_ID FIXED_PARTITION_ID(storage_partition)

static struct stream_flash_ctx sf_ctx;
static uint8_t sf_buf[CONFIG_STREAM_FLASH_BUFFER_SIZE];

static const struct device *flash_dev;
static off_t flash_offset;
static size_t flash_size;
static size_t flash_page_size;

static void stream_flash_setup(void)
{
    int rc;
    const struct flash_area *fa;
    struct flash_pages_info page_info;

    rc = flash_area_open(TEST_FLASH_AREA_ID, &fa);
    zassert_equal(rc, 0, "Failed to open flash area %d", TEST_FLASH_AREA_ID);

    flash_dev = fa->fa_dev;
    flash_offset = fa->fa_off;
    flash_size = fa->fa_size;

    zassert_true(device_is_ready(flash_dev), "Flash device not ready");

    rc = flash_get_parameters(flash_dev, &page_info);
    zassert_equal(rc, 0, "Failed to get flash parameters");
    flash_page_size = page_info.size;

    /* Ensure the flash area size is a multiple of page size for simplicity in tests */
    zassert_equal(flash_size % flash_page_size, 0, "Flash area size not page aligned");

    /* Erase the entire test flash area before running tests */
    rc = flash_area_erase(fa, 0, flash_size);
    zassert_equal(rc, 0, "Failed to erase flash area");

    flash_area_close(fa);
}

ZTEST_SUITE(stream_flash, NULL, stream_flash_setup, NULL, NULL, NULL);

ZTEST(stream_flash, test_stream_flash_init)
{
    int rc;

    /* Initialize stream_flash with the parameters of the dedicated test flash area */
    rc = stream_flash_init(&sf_ctx, flash_dev, flash_offset, flash_size, sf_buf, sizeof(sf_buf));
    zassert_equal(rc, 0, "stream_flash_init failed with %d", rc);
}

ZTEST(stream_flash, test_stream_flash_buffered_write_single_page)
{
    int rc;
    uint8_t write_buf[flash_page_size];
    uint8_t read_buf[flash_page_size];

    for (size_t i = 0; i < sizeof(write_buf); i++) {
        write_buf[i] = (uint8_t)i;
    }

    rc = stream_flash_init(&sf_ctx, flash_dev, flash_offset, flash_size, sf_buf, sizeof(sf_buf));
    zassert_equal(rc, 0, "stream_flash_init failed");

    rc = stream_flash_buffered_write(&sf_ctx, write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "stream_flash_buffered_write failed");

    rc = stream_flash_flush(&sf_ctx);
    zassert_equal(rc, 0, "stream_flash_flush failed");

    rc = flash_read(flash_dev, flash_offset, read_buf, sizeof(read_buf));
    zassert_equal(rc, 0, "flash_read failed");

    zassert_mem_equal(write_buf, read_buf, sizeof(write_buf), "Data mismatch");
}

ZTEST(stream_flash, test_stream_flash_buffered_write_multi_page)
{
    int rc;
    size_t num_pages = 2;
    size_t total_size = num_pages * flash_page_size;
    uint8_t write_buf[total_size];
    uint8_t read_buf[total_size];

    /* Ensure we don't write beyond the allocated flash_size */
    zassert_true(total_size <= flash_size, "Test data size exceeds flash area size");

    for (size_t i = 0; i < sizeof(write_buf); i++) {
        write_buf[i] = (uint8_t)i;
    }

    rc = stream_flash_init(&sf_ctx, flash_dev, flash_offset, flash_size, sf_buf, sizeof(sf_buf));
    zassert_equal(rc, 0, "stream_flash_init failed");

    rc = stream_flash_buffered_write(&sf_ctx, write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "stream_flash_buffered_write failed");

    rc = stream_flash_flush(&sf_ctx);
    zassert_equal(rc, 0, "stream_flash_flush failed");

    rc = flash_read(flash_dev, flash_offset, read_buf, sizeof(read_buf));
    zassert_equal(rc, 0, "flash_read failed");

    zassert_mem_equal(write_buf, read_buf, sizeof(write_buf), "Data mismatch");
}

ZTEST(stream_flash, test_stream_flash_buffered_write_unaligned)
{
    /* This test is skipped as stream_flash_buffered_write expects page-aligned writes */
    ztest_test_skip();
}

ZTEST(stream_flash, test_stream_flash_buffered_write_whole_page)
{
    int rc;
    uint8_t write_buf[flash_page_size];
    uint8_t read_buf[flash_page_size];

    for (size_t i = 0; i < sizeof(write_buf); i++) {
        write_buf[i] = (uint8_t)i;
    }

    rc = stream_flash_init(&sf_ctx, flash_dev, flash_offset, flash_size, sf_buf, sizeof(sf_buf));
    zassert_equal(rc, 0, "stream_flash_init failed");

    rc = stream_flash_buffered_write(&sf_ctx, write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "stream_flash_buffered_write failed");

    rc = stream_flash_flush(&sf_ctx);
    zassert_equal(rc, 0, "stream_flash_flush failed");

    rc = flash_read(flash_dev, flash_offset, read_buf, sizeof(read_buf));
    zassert_equal(rc, 0, "flash_read failed");

    zassert_mem_equal(write_buf, read_buf, sizeof(write_buf), "Data mismatch");
}

ZTEST(stream_flash, test_stream_flash_bytes_buffered)
{
    int rc;
    uint8_t write_buf[flash_page_size / 2]; /* Half a page */

    for (size_t i = 0; i < sizeof(write_buf); i++) {
        write_buf[i] = (uint8_t)i;
    }

    rc = stream_flash_init(&sf_ctx, flash_dev, flash_offset, flash_size, sf_buf, sizeof(sf_buf));
    zassert_equal(rc, 0, "stream_flash_init failed");

    rc = stream_flash_buffered_write(&sf_ctx, write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "stream_flash_buffered_write failed");

    zassert_equal(stream_flash_bytes_buffered(&sf_ctx), sizeof(write_buf), "Incorrect bytes buffered");

    rc = stream_flash_flush(&sf_ctx);
    zassert_equal(rc, 0, "stream_flash_flush failed");

    zassert_equal(stream_flash_bytes_buffered(&sf_ctx), 0, "Bytes buffered not cleared after flush");
}

ZTEST(stream_flash, test_stream_flash_bytes_written)
{
    int rc;
    uint8_t write_buf[flash_page_size];

    for (size_t i = 0; i < sizeof(write_buf); i++) {
        write_buf[i] = (uint8_t)i;
    }

    rc = stream_flash_init(&sf_ctx, flash_dev, flash_offset, flash_size, sf_buf, sizeof(sf_buf));
    zassert_equal(rc, 0, "stream_flash_init failed");

    zassert_equal(stream_flash_bytes_written(&sf_ctx), 0, "Initial bytes written not zero");

    rc = stream_flash_buffered_write(&sf_ctx, write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "stream_flash_buffered_write failed");

    rc = stream_flash_flush(&sf_ctx);
    zassert_equal(rc, 0, "stream_flash_flush failed");

    zassert_equal(stream_flash_bytes_written(&sf_ctx), sizeof(write_buf), "Incorrect bytes written");
}

ZTEST(stream_flash, test_stream_flash_flush)
{
    int rc;
    uint8_t write_buf[flash_page_size / 2]; /* Half a page */
    uint8_t read_buf[flash_page_size];

    for (size_t i = 0; i < sizeof(write_buf); i++) {
        write_buf[i] = (uint8_t)i;
    }

    rc = stream_flash_init(&sf_ctx, flash_dev, flash_offset, flash_size, sf_buf, sizeof(sf_buf));
    zassert_equal(rc, 0, "stream_flash_init failed");

    rc = stream_flash_buffered_write(&sf_ctx, write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "stream_flash_buffered_write failed");

    /* Data should not be on flash yet */
    rc = flash_read(flash_dev, flash_offset, read_buf, sizeof(read_buf));
    zassert_equal(rc, 0, "flash_read failed");
    zassert_not_mem_equal(write_buf, read_buf, sizeof(write_buf), "Data written prematurely");

    rc = stream_flash_flush(&sf_ctx);
    zassert_equal(rc, 0, "stream_flash_flush failed");

    /* Data should now be on flash */
    rc = flash_read(flash_dev, flash_offset, read_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "flash_read failed");
    zassert_mem_equal(write_buf, read_buf, sizeof(write_buf), "Data mismatch after flush");
}
